import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getLatestMovies } from '../api/tmdb';

function MovieDetail() {
  const { id } = useParams();
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchMovieDetail = async () => {
      setLoading(true);
      const movies = await getLatestMovies();
      // ID가 일치하는 영화 찾기 (숫자/문자열 비교 대응)
      const found = movies.find((m) => String(m.id) === String(id)) || movies[0];
      setMovie(found);
      setLoading(false);
    };
    fetchMovieDetail();
  }, [id]);

  if (loading) {
    return (
      <div className="w-full min-h-screen bg-white flex items-center justify-center text-zinc-800" style={{ fontFamily: 'Pretendard, sans-serif' }}>
        <p className="text-sm font-bold animate-pulse text-[#503396]">영화 정보를 불러오는 중...</p>
      </div>
    );
  }

  const posterUrl = movie?.poster_path 
    ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` 
    : "https://via.placeholder.com/300x450?text=No+Image";

  return (
    <div className="w-full min-h-screen bg-white text-zinc-800 pb-24" style={{ fontFamily: 'Pretendard, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', WebkitFontSmoothing: 'antialiased' }}>
      
      {/* 상단 타이틀 및 백 버튼 영역 */}
      <div className="max-w-5xl mx-auto px-6 pt-10">
        <button 
          onClick={() => navigate(-1)} 
          className="text-xs font-bold text-zinc-500 hover:text-[#503396] mb-4 transition"
        >
          &larr; 이전으로
        </button>
        <h2 className="text-2xl font-black tracking-tight text-zinc-900">{movie?.title}</h2>
        <p className="text-xs text-zinc-500 mt-1">개봉일 {movie?.openDt || '2026.08.05'} &bull; 예매율 {movie?.rate || '10.2%'}</p>
      </div>

      {/* 상세 콘텐츠 영역 */}
      <div className="max-w-5xl mx-auto px-6 mt-6">
        <div className="bg-white border border-zinc-200 rounded-2xl p-6 shadow-sm flex flex-col md:flex-row gap-8">
          
          {/* 영화 포스터 */}
          <div className="w-full md:w-72 flex-shrink-0">
            <div className="rounded-xl overflow-hidden shadow-md">
              <img src={posterUrl} alt={movie?.title} className="w-full h-auto object-cover block" />
            </div>
          </div>

          {/* 영화 상세 정보 (감독, 출연진, 줄거리) */}
          <div className="flex flex-col justify-between flex-grow space-y-6">
            
            <div className="space-y-4">
              {/* 평점 및 관람객 정보 박스 */}
              <div className="flex items-center gap-6 bg-zinc-50 p-4 rounded-xl border border-zinc-200 text-xs font-bold text-zinc-700">
                <div>
                  <span className="text-zinc-400 block text-[10px]">실관람 평점</span>
                  <span className="text-sm font-black text-[#503396]">M 9.5</span>
                </div>
                <div className="border-l border-zinc-200 pl-6">
                  <span className="text-zinc-400 block text-[10px]">박스오피스 순위</span>
                  <span className="text-sm font-black text-zinc-900">{movie?.rank || '1'}위</span>
                </div>
                <div className="border-l border-zinc-200 pl-6">
                  <span className="text-zinc-400 block text-[10px]">누적관객수</span>
                  <span className="text-sm font-black text-zinc-900">{movie?.audiAcc ? Number(movie.audiAcc).toLocaleString() + '명' : '6,696,818명'}</span>
                </div>
              </div>

              {/* 스태프 및 출연진 정보 */}
              <div className="space-y-2 text-xs text-zinc-700">
                <p><strong>감독:</strong> <span className="text-zinc-900 font-semibold">{movie?.director || '정보 없음'}</span></p>
                <p><strong>등장인물:</strong> <span className="text-zinc-900 font-semibold">{movie?.cast || '정보 없음'}</span></p>
              </div>

              {/* 줄거리 */}
              <div className="space-y-1.5 pt-2 border-t border-zinc-100">
                <h4 className="text-xs font-black text-zinc-900">줄거리</h4>
                <p className="text-xs text-zinc-600 leading-relaxed font-medium">
                  {movie?.overview || '등록된 줄거리가 없습니다.'}
                </p>
              </div>
            </div>

            {/* 예매하기 버튼 */}
            <div>
              <button 
                onClick={() => navigate('/schedule')}
                className="w-full py-3.5 bg-[#503396] hover:bg-[#432a7e] text-white rounded-xl text-xs font-black transition shadow-md"
              >
                상영시간표 및 예매하기
              </button>
            </div>

          </div>

        </div>
      </div>

    </div>
  );
}

export default MovieDetail;
